examples.template:
MonarchButton({{trigger}}, variant: .primary) { isOpen = true }
    .sheet(isPresented: $isOpen) {
        MonarchPreJoinLobby(
            {{title}},
            isMicOn: $isMicOn,
            isCameraOn: $isCameraOn,
            audioLevel: 0.3,
            participants: [
                MonarchPresencePerson(id: {{participants.0}}, name: {{participants.0}}),
                MonarchPresencePerson(id: {{participants.1}}, name: {{participants.1}}),
                MonarchPresencePerson(id: {{participants.2}}, name: {{participants.2}}),
            ],
            isJoining: joined,
            labels: MonarchPreJoinLobbyLabels(cameraOff: {{cameraOff}}, cancel: {{cancel}}, join: {{join}}),
            onCancel: {},
            preview: { Color.clear },
            devices: {
                MonarchDevicePicker(
                    microphone: $microphone,
                    camera: $camera,
                    microphones: [MonarchDevicePickerDevice({{microphone.id}}, name: {{microphone.label}})],
                    cameras: [MonarchDevicePickerDevice({{camera.id}}, name: {{camera.label}})],
                    access: .granted,
                    size: .sm
                )
            },
            onJoin: { joined = true }
        )
        .padding()
    }

examples.setupTemplate:
@State private var isOpen = false
@State private var isMicOn = {{micOn}}
@State private var isCameraOn = {{cameraOn}}
@State private var microphone: String? = {{microphone.id}}
@State private var camera: String? = {{camera.id}}
@State private var joined = false

examples.setup:
@State private var isOpen = false
@State private var isMicOn = true
@State private var isCameraOn = false
@State private var microphone: String? = "mic-desk"
@State private var camera: String? = "cam-built-in"
@State private var joined = false

examples.code:
MonarchButton("Join call", variant: .primary) { isOpen = true }
    .sheet(isPresented: $isOpen) {
        MonarchPreJoinLobby(
            "Join Weekly planning",
            isMicOn: $isMicOn,
            isCameraOn: $isCameraOn,
            audioLevel: 0.3,
            participants: [
                MonarchPresencePerson(id: "Robin Park", name: "Robin Park"),
                MonarchPresencePerson(id: "Alex Chen", name: "Alex Chen"),
                MonarchPresencePerson(id: "Jordan Diaz", name: "Jordan Diaz"),
            ],
            isJoining: joined,
            labels: MonarchPreJoinLobbyLabels(cameraOff: "Camera is off", cancel: "Cancel", join: "Join now"),
            onCancel: {},
            preview: { Color.clear },
            devices: {
                MonarchDevicePicker(
                    microphone: $microphone,
                    camera: $camera,
                    microphones: [MonarchDevicePickerDevice("mic-desk", name: "Desk microphone")],
                    cameras: [MonarchDevicePickerDevice("cam-built-in", name: "Built-in camera")],
                    access: .granted,
                    size: .sm
                )
            },
            onJoin: { joined = true }
        )
        .padding()
    }

